"use client";

import type { ReactNode, FC } from "react";
import { cn } from "@aomi-labs/react";
import { NetworkSelect } from "./network-select";
import { ModelSelect } from "./model-select";
import { AppSelect } from "./app-select";
import { ApiKeyInput } from "./api-key-input";
import { ConnectButton } from "./connect-button";
import { SecretInput } from "./secret-input";

// =============================================================================
// Types
// =============================================================================

export type ControlBarProps = {
  className?: string;
  /** Custom controls to render alongside built-in ones */
  children?: ReactNode;
  /** Hide the model selector */
  hideModel?: boolean;
  /** Hide the App selector */
  hideApp?: boolean;
  /** Hide the API key input */
  hideApiKey?: boolean;
  /** Hide the wallet connect button (default: true) */
  hideWallet?: boolean;
  /** Hide the network selector (default: false) */
  hideNetwork?: boolean;
  /** Hide the secrets input */
  hideSecrets?: boolean;
};

// =============================================================================
// Main Component
// =============================================================================

export const ControlBar: FC<ControlBarProps> = ({
  className,
  children,
  hideModel = false,
  hideApp = false,
  hideApiKey = false,
  hideWallet = true,
  hideNetwork = false,
  hideSecrets = false,
}) => {
  return (
    <div className={cn("flex items-center gap-1", className)}>
      {!hideNetwork && <NetworkSelect />}
      {!hideModel && <ModelSelect />}
      {!hideApp && <AppSelect />}
      {!hideWallet && <ConnectButton />}
      {!hideSecrets && <SecretInput />}
      {children}
      {!hideApiKey && <ApiKeyInput />}
    </div>
  );
};

// =============================================================================
// Re-exports for granular usage
// =============================================================================

export { ModelSelect, type ModelSelectProps } from "./model-select";
export { AppSelect, type AppSelectProps } from "./app-select";
export { ApiKeyInput, type ApiKeyInputProps } from "./api-key-input";
export {
  ConnectButton,
  type ConnectButtonProps,
} from "./connect-button";
export { NetworkSelect, type NetworkSelectProps } from "./network-select";
export { SecretInput, type SecretInputProps } from "./secret-input";

"use client";

import { useEffect, useState, type FC } from "react";
import { ChevronDownIcon, CheckIcon } from "lucide-react";
import { useAomiRuntime, useControl, cn } from "@aomi-labs/react";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
  CommandInput,
  CommandSeparator,
} from "@/components/ui/command";
import {
  groupModelsByVendor,
  getVendorForModel,
  AUTO_MODE_LABEL,
  resolveAutoModel,
} from "./model-metadata";
import { AutoModeIcon, getVendorIcon } from "@/components/icons";

export type ModelSelectProps = {
  className?: string;
  placeholder?: string;
};

export const ModelSelect: FC<ModelSelectProps> = ({
  className,
  placeholder = "Select model",
}) => {
  const {
    state,
    getAvailableModels,
    getCurrentThreadControl,
    onModelSelect,
  } = useControl();
  const { isRunning } = useAomiRuntime();
  const [open, setOpen] = useState(false);

  useEffect(() => {
    void getAvailableModels();
  }, [getAvailableModels]);

  const threadControl = getCurrentThreadControl();
  const rawSelected = threadControl.model;
  const modelMode =
    threadControl.modelMode ?? (rawSelected === null ? "auto" : "manual");
  const models = state.availableModels;

  const autoBackendModel = resolveAutoModel(models);
  const isAuto = modelMode === "auto";
  const selectedModel = isAuto
    ? autoBackendModel
    : (rawSelected ?? state.defaultModel ?? models[0]);

  if (models.length === 0) {
    return (
      <Button
        variant="ghost"
        disabled
        className={cn(
          "h-8 w-auto min-w-[100px] rounded-full px-2 text-xs",
          "text-muted-foreground",
          className,
        )}
      >
        <span className="truncate">Loading...</span>
      </Button>
    );
  }

  const groups = groupModelsByVendor(models);

  // Display label for the trigger button
  const triggerLabel = isAuto ? AUTO_MODE_LABEL : selectedModel || placeholder;

  const handleSelect = (model: string) => {
    if (isRunning) return;
    setOpen(false);
    void onModelSelect(model, { mode: "manual" }).catch((err) => {
      console.error("[ModelSelect] onModelSelect failed:", err);
    });
  };

  const handleAutoSelect = () => {
    if (!autoBackendModel || isRunning) return;
    setOpen(false);
    void onModelSelect(autoBackendModel, { mode: "auto" }).catch((err) => {
      console.error("[ModelSelect] auto onModelSelect failed:", err);
    });
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          role="combobox"
          aria-expanded={open}
          disabled={isRunning}
          className={cn(
            "h-8 w-auto min-w-0 justify-between rounded-full px-0.5 text-xs md:min-w-[100px] md:px-3",
            "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
            isRunning && "cursor-not-allowed opacity-50",
            className,
          )}
        >
          <div className="flex items-center gap-px md:gap-1.5">
            {(() => {
              if (isAuto) {
                return <AutoModeIcon className="h-3 w-3 shrink-0 opacity-60" />;
              }
              if (selectedModel) {
                const vendor = getVendorForModel(selectedModel);
                const VIcon = getVendorIcon(vendor.id);
                if (VIcon)
                  return <VIcon className="h-3 w-3 shrink-0 opacity-60" />;
              }
              return null;
            })()}
            <span className="truncate">{triggerLabel}</span>
          </div>
          <ChevronDownIcon className="ml-0 h-3 w-3 shrink-0 opacity-50 md:ml-2" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        sideOffset={4}
        className="w-[280px] overflow-hidden rounded-xl p-0"
        onOpenAutoFocus={(e) => {
          if (window.matchMedia("(max-width: 767px)").matches) {
            e.preventDefault();
          }
        }}
      >
        <Command className="rounded-xl">
          <CommandInput placeholder="Search models..." />
          <CommandList>
            <CommandEmpty>No models found.</CommandEmpty>

            {/* Auto mode — pinned at top */}
            <CommandGroup>
              <CommandItem
                value="auto"
                disabled={isRunning}
                onSelect={handleAutoSelect}
                className="flex items-center justify-between gap-2"
              >
                <div className="flex items-center gap-2">
                  <span
                    className={cn(
                      "flex h-5 w-5 shrink-0 items-center justify-center rounded-md",
                      "bg-primary/10 text-primary",
                    )}
                  >
                    <AutoModeIcon className="h-3.5 w-3.5" />
                  </span>
                  <div className="flex flex-col">
                    <span className="font-medium">{AUTO_MODE_LABEL}</span>
                    <span className="text-muted-foreground text-xs">
                      Best balance of speed & cost
                    </span>
                  </div>
                </div>
                {isAuto && <CheckIcon className="h-4 w-4 shrink-0" />}
              </CommandItem>
            </CommandGroup>

            <CommandSeparator />

            {/* Vendor-grouped models */}
            {groups.map((group) => {
              const VendorIcon = getVendorIcon(group.vendor.id);
              return (
                <CommandGroup
                  key={group.vendor.id}
                  heading={group.vendor.label}
                >
                  {group.models.map((model) => (
                    <CommandItem
                      key={model}
                      value={model}
                      disabled={isRunning}
                      onSelect={() => handleSelect(model)}
                      className="flex items-center justify-between gap-2"
                    >
                      <div className="flex items-center gap-2">
                        <span
                          className={cn(
                            "flex h-5 w-5 shrink-0 items-center justify-center rounded-md",
                            "bg-muted text-muted-foreground",
                          )}
                        >
                          {VendorIcon ? (
                            <VendorIcon className="h-3.5 w-3.5" />
                          ) : (
                            <span className="text-[10px] font-medium">
                              {group.vendor.abbr}
                            </span>
                          )}
                        </span>
                        <span className="truncate">{model}</span>
                      </div>
                      {!isAuto && selectedModel === model && (
                        <CheckIcon className="h-4 w-4 shrink-0" />
                      )}
                    </CommandItem>
                  ))}
                </CommandGroup>
              );
            })}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};

/**
 * Model metadata for UI display.
 * Maps raw backend model strings to vendor info and grouping hints.
 */

export { resolveAutoModel } from "@aomi-labs/react";

// =============================================================================
// Vendor definitions
// =============================================================================

export type VendorInfo = {
  id: string;
  label: string;
  /** 1-2 letter abbreviation for the avatar fallback */
  abbr: string;
};

const VENDORS: Record<string, VendorInfo> = {
  anthropic: { id: "anthropic", label: "Anthropic", abbr: "A" },
  openai: { id: "openai", label: "OpenAI", abbr: "O" },
  google: { id: "google", label: "Google", abbr: "G" },
  meta: { id: "meta", label: "Meta", abbr: "M" },
  mistral: { id: "mistral", label: "Mistral", abbr: "Mi" },
  deepseek: { id: "deepseek", label: "DeepSeek", abbr: "D" },
  xai: { id: "xai", label: "xAI", abbr: "X" },
  cohere: { id: "cohere", label: "Cohere", abbr: "C" },
  glm: { id: "glm", label: "GLM", abbr: "G" },
  moonshot: { id: "moonshot", label: "Moonshot AI", abbr: "K" },
  unknown: { id: "unknown", label: "Other", abbr: "?" },
};

// =============================================================================
// Vendor detection from model string
// =============================================================================

const VENDOR_PATTERNS: [RegExp, string][] = [
  [/^claude/i, "anthropic"],
  [/^gpt|^o[1-9]|^chatgpt|^dall-e/i, "openai"],
  [/^gemini|^palm/i, "google"],
  [/^llama|^meta-llama/i, "meta"],
  [/^mistral|^mixtral|^codestral|^pixtral/i, "mistral"],
  [/^deepseek/i, "deepseek"],
  [/^grok/i, "xai"],
  [/^command/i, "cohere"],
  [/^glm|^chatglm|^zai|^z\.ai|^zhipu/i, "glm"],
  [/^kimi|^moonshot/i, "moonshot"],
];

export function getVendorForModel(model: string): VendorInfo {
  const lower = model.toLowerCase();
  for (const [pattern, vendorId] of VENDOR_PATTERNS) {
    if (pattern.test(lower)) {
      return VENDORS[vendorId]!;
    }
  }
  return VENDORS.unknown!;
}

// =============================================================================
// Group models by vendor, sorted
// =============================================================================

export type ModelGroup = {
  vendor: VendorInfo;
  models: string[];
};

export function groupModelsByVendor(models: string[]): ModelGroup[] {
  const grouped = new Map<string, string[]>();

  for (const model of models) {
    const vendor = getVendorForModel(model);
    const existing = grouped.get(vendor.id) ?? [];
    existing.push(model);
    grouped.set(vendor.id, existing);
  }

  // Sort vendor groups alphabetically by label
  return Array.from(grouped.entries())
    .map(([vendorId, vendorModels]) => ({
      vendor: VENDORS[vendorId] ?? VENDORS.unknown!,
      models: [...vendorModels].sort((a, b) =>
        a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }),
      ),
    }))
    .sort((a, b) => {
      if (a.vendor.id === "unknown") return 1;
      if (b.vendor.id === "unknown") return -1;
      return a.vendor.label.localeCompare(b.vendor.label);
    });
}

// =============================================================================
// Auto mode
// =============================================================================

/** The display label shown in the trigger when auto mode is active. */
export const AUTO_MODE_LABEL = "Auto";

/**
 * App metadata for UI display.
 * Maps raw backend app ids to display names, categories, and aliases.
 */

import type { AomiAppDescriptor } from "@aomi-labs/client";

export type AppInfo = {
  /** Raw app id sent to backend */
  id: string;
  /** Backend application scope for hosted apps. */
  applicationId?: AomiAppDescriptor["applicationId"];
  /** Human-readable display name */
  displayName: string;
  /** 1-2 letter abbreviation for avatar fallback */
  abbr: string;
  category: AppCategoryInfo;
};

export type AppCategoryInfo = {
  id: string;
  label: string;
  order: number;
};

export type AppGroup = {
  category: AppCategoryInfo;
  apps: AppInfo[];
};

const APP_CATEGORIES = {
