              Cancel
            </Button>
            <Button
              onClick={() => {
                const target = pendingTarget;
                setConfirmOpen(false);
                setPendingTarget(null);
                if (target) {
                  void applyTarget(target);
                }
              }}
            >
              Switch Network
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

"use client";

import { useState, type FC } from "react";
import {
  ShieldIcon,
  CheckIcon,
  EyeIcon,
  EyeOffIcon,
  PlusIcon,
  XIcon,
} from "lucide-react";
import { useControl, cn } from "@aomi-labs/react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "@/components/ui/dialog";

export type SecretInputProps = {
  className?: string;
  title?: string;
  description?: string;
};

type SecretEntry = { name: string; value: string };

export const SecretInput: FC<SecretInputProps> = ({
  className,
  title = "Secrets",
  description = "Add API keys for third-party services. Secrets are stored in memory only and never saved to disk.",
}) => {
  const { ingestSecrets, clearSecrets } = useControl();
  const [open, setOpen] = useState(false);
  const [entries, setEntries] = useState<SecretEntry[]>([
    { name: "", value: "" },
  ]);
  const [savedNames, setSavedNames] = useState<string[]>([]);
  const [showValues, setShowValues] = useState(false);
  const [saving, setSaving] = useState(false);

  const hasSecrets = savedNames.length > 0;

  const updateEntry = (
    index: number,
    field: "name" | "value",
    val: string,
  ) => {
    setEntries((prev) => {
      const next = [...prev];
      next[index] = { ...next[index], [field]: val };
      return next;
    });
  };

  const addEntry = () => {
    setEntries((prev) => [...prev, { name: "", value: "" }]);
  };

  const removeEntry = (index: number) => {
    setEntries((prev) => prev.filter((_, i) => i !== index));
  };

  const validEntries = entries.filter(
    (e) => e.name.trim() && e.value.trim(),
  );

  const handleSave = async () => {
    if (validEntries.length === 0) return;
    setSaving(true);
    try {
      const secrets: Record<string, string> = {};
      for (const entry of validEntries) {
        secrets[entry.name.trim()] = entry.value.trim();
      }
      await ingestSecrets(secrets);
      setSavedNames((prev) => [
        ...new Set([...prev, ...Object.keys(secrets)]),
      ]);
      setEntries([{ name: "", value: "" }]);
      setOpen(false);
    } catch (error) {
      console.error("[SecretInput] Failed to ingest secrets:", error);
    } finally {
      setSaving(false);
    }
  };

  const handleClear = async () => {
    setSaving(true);
    try {
      await clearSecrets();
      setSavedNames([]);
      setEntries([{ name: "", value: "" }]);
    } catch (error) {
      console.error("[SecretInput] Failed to clear secrets:", error);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className={cn("relative rounded-full", className)}
          aria-label={hasSecrets ? "Secrets configured" : "Add secrets"}
        >
          <ShieldIcon
            className={cn("h-4 w-4", hasSecrets && "text-green-500")}
          />
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-[340px] rounded-3xl pl-4">
        <DialogHeader className="border-0">
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <div className="grid gap-3 py-4">
          {hasSecrets && (
            <div className="text-muted-foreground text-xs">
              <CheckIcon className="mr-1 inline h-3 w-3 text-green-500" />
              {savedNames.length} secret{savedNames.length > 1 ? "s" : ""}{" "}
              configured: {savedNames.join(", ")}
            </div>
          )}

          {entries.map((entry, index) => (
            <div key={index} className="flex items-end gap-2">
              <div className="grid flex-1 gap-1">
                {index === 0 && (
                  <Label className="text-xs">Name</Label>
                )}
                <Input
                  type="text"
                  placeholder="MY_API_KEY"
                  value={entry.name}
                  onChange={(e) => updateEntry(index, "name", e.target.value)}
                  className="h-8 rounded-full text-xs"
                />
              </div>
              <div className="grid flex-1 gap-1">
                {index === 0 && (
                  <Label className="flex items-center gap-1 text-xs">
                    Value
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="h-4 w-4 p-0 hover:bg-transparent"
                      onClick={() => setShowValues(!showValues)}
                      aria-label={showValues ? "Hide values" : "Show values"}
                    >
                      {showValues ? (
                        <EyeIcon className="h-3 w-3" />
                      ) : (
                        <EyeOffIcon className="h-3 w-3" />
                      )}
                    </Button>
                  </Label>
                )}
                <Input
                  type={showValues ? "text" : "password"}
                  placeholder="sk-..."
                  value={entry.value}
                  onChange={(e) => updateEntry(index, "value", e.target.value)}
                  className="h-8 rounded-full text-xs"
                />
              </div>
              {entries.length > 1 && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 shrink-0 rounded-full"
                  onClick={() => removeEntry(index)}
                  aria-label="Remove entry"
                >
                  <XIcon className="h-3 w-3" />
                </Button>
              )}
            </div>
          ))}

          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="w-fit rounded-full text-xs"
            onClick={addEntry}
          >
            <PlusIcon className="mr-1 h-3 w-3" />
            Add another
          </Button>
        </div>
        <DialogFooter>
          {hasSecrets && (
            <Button
              variant="outline"
              className="rounded-full"
              onClick={() => void handleClear()}
              disabled={saving}
            >
              Clear all
            </Button>
          )}
          <Button
            className="rounded-full"
            onClick={() => void handleSave()}
            disabled={validEntries.length === 0 || saving}
          >
            Save
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useCallback, useMemo, useState } from "react";
import { useControl, useNotification } from "@aomi-labs/react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

const PROVIDERS = [
  { id: "openai", label: "OpenAI" },
  { id: "anthropic", label: "Anthropic" },
  { id: "openrouter", label: "OpenRouter" },
] as const;

type ProviderId = (typeof PROVIDERS)[number]["id"];

export function PaymentRequiredGate() {
  const { notifications, dismissNotification, showNotification } =
    useNotification();
  const { setByok } = useControl();
  const paymentNotification = notifications.find(
    (notification) => notification.kind === "payment_required",
  );

  const [selectedProvider, setSelectedProvider] =
    useState<ProviderId>("openai");
  const [label, setLabel] = useState("");
  const [apiKey, setApiKey] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canSave = useMemo(
    () => !saving && apiKey.trim().length > 0,
    [apiKey, saving],
  );

  const handleDismiss = useCallback(() => {
    if (paymentNotification) {
      dismissNotification(paymentNotification.id);
    }
    setError(null);
  }, [dismissNotification, paymentNotification]);

  const handleSave = useCallback(async () => {
    if (!canSave) return;

    setSaving(true);
    setError(null);
    try {
      await setByok(
        selectedProvider,
        apiKey.trim(),
        label.trim() || undefined,
      );
      setApiKey("");
      setLabel("");
      handleDismiss();
      // Failed user message stays in the thread with `aomiSendStatus: failed`.
      // We don't auto-retry (could be unexpected if the user moved on), but
      // we do tell them the gate is cleared so the modal isn't silently gone.
      showNotification({
        type: "success",
        title: "Provider key saved — resend your message to continue.",
        duration: 6000,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save BYOK key");
    } finally {
      setSaving(false);
    }
  }, [
    apiKey,
    canSave,
    handleDismiss,
    label,
    selectedProvider,
    setByok,
    showNotification,
  ]);

  if (!paymentNotification) return null;

  return (
    <div
      className="bg-background/85 absolute inset-0 z-40 flex items-center justify-center px-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="payment-required-title"
    >
      <div className="bg-card border-input w-full max-w-lg rounded-3xl border p-7 shadow-2xl md:p-8">
        <div className="space-y-3">
          <h2
            id="payment-required-title"
            className="text-foreground text-2xl font-semibold tracking-normal"
          >
            Set up BYOK
          </h2>
          <p className="text-muted-foreground text-base leading-7">
            You&apos;re out of Aomi credits. Add an LLM provider key to keep
            chatting with BYOK. x402 and MPP payments are coming to the
            platform.
          </p>
        </div>

        <div className="mt-6 flex flex-wrap gap-2">
          {PROVIDERS.map((provider) => {
            const active = selectedProvider === provider.id;
            return (
              <button
                key={provider.id}
                type="button"
                onClick={() => setSelectedProvider(provider.id)}
                className={[
                  "rounded-full border px-5 py-2 text-sm font-medium transition-colors",
                  active
                    ? "border-foreground bg-foreground text-background"
                    : "border-border bg-background text-foreground hover:border-foreground/40",
                ].join(" ")}
              >
                {provider.label}
              </button>
            );
          })}
        </div>

        <div className="mt-6 grid gap-4">
          <Input
            value={label}
            onChange={(event) => setLabel(event.target.value)}
            placeholder="Label (optional)"
            className="h-12 rounded-full px-5 text-base shadow-inner"
          />
          <Input
            value={apiKey}
            onChange={(event) => setApiKey(event.target.value)}
            placeholder="Paste LLM provider key"
            type="password"
            autoComplete="off"
            className="h-12 rounded-full px-5 text-base shadow-inner"
          />
        </div>

        <p className="text-muted-foreground mt-4 text-sm leading-6">
          Keys are stored in your browser and synchronized with the backend
          vault. BYOK usage is recorded, but it does not consume Aomi credits.
        </p>

        {error && <p className="text-destructive mt-3 text-sm">{error}</p>}

        <div className="mt-7 flex flex-col-reverse gap-3 sm:flex-row sm:items-center sm:justify-end">
          <button
            type="button"
            onClick={handleDismiss}
            className="text-foreground hover:text-muted-foreground h-11 px-4 text-sm font-medium transition-colors"
          >
            Not now
          </button>
          <Button
            type="button"
            onClick={() => {
              void handleSave();
            }}
            disabled={!canSave}
            className="h-11 rounded-full px-7"
          >
            {saving ? "Saving..." : "Save and continue"}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Fragment, useEffect, useState, type FC } from "react";
import { ChevronsUpDownIcon, UnfoldVerticalIcon } from "lucide-react";
import { cn, getChainInfo } from "@aomi-labs/react";
import {
  useAomiWalletKit,
  formatWalletAddress,
  signOutAndDisconnect,
} from "../../lib/wallet-kit";
import { WalletIconSlot } from "./wallet-icon-slot";
import { WalletPicker } from "./wallet-picker";
import { WalletPickerProvider, useWalletPicker } from "./wallet-picker-context";
import { AccountMenu } from "./account-menu";
import { DisconnectConfirmDialog } from "./disconnect-confirm-dialog";
import type { WalletAccountMenuOptions } from "./account-menu-types";

export type DualWalletBarProps = {
  families: Array<"evm" | "solana">;
  className?: string;
  onConnectionChange?: (connected: boolean) => void;
  /** Optional account menu layer — portal passes live allowance + action callbacks. */
  accountMenu?: WalletAccountMenuOptions;
};

type ConnectedWallet = {
  family: "evm" | "solana";
  walletName?: string;
  address: string;
  detail?: string;
};

const AVATAR_SIZE = 28;

/** Longer middle-truncated address, revealed when the bar has room to grow. */
function longAddress(address: string): string {
  if (address.length <= 20) return address;
  return `${address.slice(0, 12)}..${address.slice(-8)}`;
}

function solanaClusterLabel(cluster?: string): string | undefined {
  if (!cluster) return undefined;
  const name = cluster.replace("solana:", "");
  if (!name) return undefined;
  return name.charAt(0).toUpperCase() + name.slice(1);
}

const DualWalletBarInner: FC<DualWalletBarProps> = ({
  families,
  className,
  onConnectionChange,
  accountMenu,
}) => {
  const adapter = useAomiWalletKit();
  const identity = adapter.identity;
  const { openPicker } = useWalletPicker();
  const [menuOpen, setMenuOpen] = useState(false);
  const [disconnectOpen, setDisconnectOpen] = useState(false);
  const [disconnectBusy, setDisconnectBusy] = useState(false);

  const connected = Boolean(identity.address || identity.svmAddress);
  const accountMenuEnabled = Boolean(accountMenu?.enabled);
  const activeEvmAccount = adapter.accounts.find(
    (account) => account.family === "evm" && account.active,
  );
  const activeSolanaAccount = adapter.accounts.find(
    (account) => account.family === "svm" && account.active,
  );
  const connectedWallets = families
    .map((family): ConnectedWallet | null =>
      family === "evm"
        ? identity.address
          ? {
              family,
              walletName: activeEvmAccount?.walletName,
              address: identity.address,
              detail: getChainInfo(activeEvmAccount?.chainId ?? identity.chainId)
                ?.name,
            }
          : null
        : identity.svmAddress
          ? {
              family,
              walletName:
                activeSolanaAccount?.walletName ??
                identity.svmWalletName,
              address: identity.svmAddress,
              detail: solanaClusterLabel(identity.svmCluster),
            }
          : null,
    )
    .filter((wallet): wallet is ConnectedWallet => wallet !== null);
  const singleWallet = connectedWallets.length === 1;
  const primaryWallet = connectedWallets[0];
  const networkDetail = connectedWallets
    .map((wallet) => wallet.detail)
    .filter(Boolean)
    .join(" · ");
  const secondaryLine = accountMenuEnabled
    ? (accountMenu?.secondaryLine ?? "Allowance —")
    : connectedWallets.some((wallet) => wallet.detail)
      ? networkDetail
      : undefined;
  const walletLabel =
    accountMenu?.walletLabel ??
    primaryWallet?.walletName ??
    (primaryWallet?.family === "solana" ? "Solana" : "Ethereum");
  const visibleAddress =
    identity.address ?? identity.svmAddress ?? primaryWallet?.address;

  useEffect(() => {
    onConnectionChange?.(identity.isConnected);
  }, [identity.isConnected, onConnectionChange]);

  useEffect(() => {
    if (!connected) {
      setMenuOpen(false);
      setDisconnectOpen(false);
    }
  }, [connected]);

  const handleChipClick = () => {
    if (accountMenuEnabled && connected) {
      setMenuOpen((open) => !open);
      return;
    }
    openPicker();
  };

  const handleManageWallets = () => {
    setMenuOpen(false);
    openPicker();
  };

  const handleDisconnectRequest = () => {
    setMenuOpen(false);
    setDisconnectOpen(true);
  };

  const handleDisconnectConfirm = async () => {
    setDisconnectBusy(true);
    try {
      if (accountMenu?.onDisconnect) {
        await accountMenu.onDisconnect();
      } else {
        await signOutAndDisconnect(adapter);
      }
      setDisconnectOpen(false);
    } catch (err) {
      // Keep the dialog open for a retry; if the wallet drop itself landed,
      // the connected-state effect above closes it.
      console.warn("[DualWalletBar] disconnect failed", err);
    } finally {
      setDisconnectBusy(false);
    }
  };

  const wrapMenuAction = (action?: () => void) => {
    if (!action) return undefined;
    return () => {
      setMenuOpen(false);
      action();
    };
  };

  const chipClassName = cn(
    "inline-flex w-full items-center justify-between gap-2.5 whitespace-nowrap text-left transition-colors",
    "border-aomi-border text-aomi-fg hover:bg-aomi-hover/80 bg-transparent",
    "focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2",
    accountMenuEnabled
      ? "rounded-lg border p-2.5"
      : "@container rounded-xl border p-3",
    className,
  );

  const chipChevron = accountMenuEnabled ? (
    <UnfoldVerticalIcon className="text-aomi-muted size-4 shrink-0" />
  ) : (
    <ChevronsUpDownIcon className="text-aomi-muted size-4 shrink-0" />
  );

  return (
    <>
      <div className="relative w-full">
        <button
          type="button"
          onClick={handleChipClick}
          className={chipClassName}
          aria-label={
            accountMenuEnabled && connected ? "Open account menu" : "Manage wallets"
          }
          aria-expanded={accountMenuEnabled && connected ? menuOpen : undefined}
        >
          {connected && connectedWallets.length ? (
            accountMenuEnabled ? (
              <span className="flex min-w-0 flex-1 items-center gap-2.5">
                <WalletIconSlot
                  label={walletLabel}
                  size={AVATAR_SIZE}
                  className="ring-aomi-border bg-aomi-surface-2 shrink-0 rounded-full ring-1"
                />
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="text-aomi-fg truncate font-mono text-[12px] font-medium leading-none tracking-tight">
                    {primaryWallet ? longAddress(primaryWallet.address) : "Connected"}
                  </span>
                  {secondaryLine ? (
                    <span className="text-aomi-muted truncate text-[11px] leading-none">
                      {secondaryLine}
                    </span>
                  ) : null}
                </span>
              </span>
            ) : (
              <span className="flex min-w-0 items-center gap-2.5">
                <span className="flex shrink-0 items-center">
                  {connectedWallets.map((wallet, index) => (
                    <WalletIconSlot
                      key={wallet.family}
                      label={
                        wallet.walletName ??
                        (wallet.family === "solana" ? "Solana" : "Ethereum")
                      }
                      size={AVATAR_SIZE}
                      className={cn(
                        "ring-aomi-border bg-aomi-surface-2 rounded-full ring-1",
                        index > 0 && "-ml-2",
                      )}
                    />
                  ))}
                </span>
                <span className="flex min-w-0 flex-col">
                  <span className="min-w-0 truncate text-[13px] font-medium">
                    {connectedWallets.map((wallet, index) => (
                      <Fragment key={wallet.family}>
                        {index > 0 ? (
                          <span className="text-aomi-muted/60">{" / "}</span>
                        ) : null}
                        {singleWallet ? (
                          <>
                            <span className="@[15rem]:hidden">
                              {formatWalletAddress(wallet.address)}
                            </span>
                            <span className="hidden @[15rem]:inline">
                              {longAddress(wallet.address)}
                            </span>
                          </>
                        ) : (
                          <span>{formatWalletAddress(wallet.address)}</span>
                        )}
                      </Fragment>
                    ))}
                  </span>
                  {secondaryLine ? (
                    <span className="text-aomi-muted min-w-0 truncate text-[11px]">
                      {secondaryLine}
                    </span>
                  ) : null}
                </span>
              </span>
            )
          ) : (
            <span className="flex h-7 min-w-0 flex-1 items-center">
              <span className="truncate text-sm font-medium">
                Connect wallet
              </span>
            </span>
          )}
          {chipChevron}
        </button>

        {accountMenuEnabled && connected ? (
          <AccountMenu
            open={menuOpen}
            address={visibleAddress}
            walletLabel={walletLabel}
            allowanceLine={accountMenu?.secondaryLine}
            noticeLine={accountMenu?.noticeLine}
            networkLabel={accountMenu?.networkLabel ?? networkDetail}
            themeLabel={accountMenu?.themeLabel}
            onClose={() => setMenuOpen(false)}
            onManageWallets={handleManageWallets}
            onSwitchNetwork={wrapMenuAction(accountMenu?.onSwitchNetwork)}
            onToggleTheme={wrapMenuAction(accountMenu?.onToggleTheme)}
            onOpenSettings={wrapMenuAction(accountMenu?.onOpenSettings)}
            onOpenDeployments={wrapMenuAction(accountMenu?.onOpenDeployments)}
            onSignIn={wrapMenuAction(accountMenu?.onSignIn)}
            onDisconnect={handleDisconnectRequest}
          />
        ) : null}
      </div>

      <DisconnectConfirmDialog
        open={disconnectOpen}
        address={visibleAddress}
        busy={disconnectBusy}
        onConfirm={() => void handleDisconnectConfirm()}
        onCancel={() => setDisconnectOpen(false)}
      />
      <WalletPicker />
    </>
  );
};

export const DualWalletBar: FC<DualWalletBarProps> = (props) => {
  return (
    <WalletPickerProvider>
      <DualWalletBarInner {...props} />
    </WalletPickerProvider>
  );
};

"use client";

import { LogOutIcon } from "lucide-react";
