        id={group.provider}
        label={providerLabel}
        provider={group.provider}
      />
      <span className="min-w-0 flex-1">
        {editing ? (
          <input
            value={draftLabel}
            onChange={(event) => onDraftLabelChange(event.target.value)}
            disabled={busy}
            aria-label={`Sign-in label for ${title}`}
