"use client";

import { formatWalletAddress } from "./identity";
import type { AomiAccount } from "./types";
import { walletKey } from "./wallet-utils";
import type { AccountWallet } from "./account/types";

export type EvmConnectionInput = {
  id: string;
  walletName: string;
  address: string;
  chainId?: number;
  provider?: string;
  walletKind?: AomiAccount["walletKind"];
};

export type SvmConnectionInput = {
  id?: string;
  publicKey: string;
  walletName?: string;
  provider?: string;
  walletKind?: AomiAccount["walletKind"];
};

const GENERIC_WALLET_NAMES = new Set(["", "injected", "browser wallet", "wallet"]);

/** A real brand name beats a generic injected label when picking the display row. */
function isRealBrandName(name: string | undefined): boolean {
  return !GENERIC_WALLET_NAMES.has((name ?? "").trim().toLowerCase());
}

export function buildAccounts(input: {
  evmConnections: readonly EvmConnectionInput[];
  activeEvmAddress?: string;
  activeEvmConnectionId?: string;
  svmConnections?: readonly SvmConnectionInput[];
  activeSvmAddress?: string;
}): AomiAccount[] {
  const accounts: AomiAccount[] = [];
  const active = input.activeEvmAddress
    ? walletKey("evm", input.activeEvmAddress)
    : undefined;
  const activeConnId = input.activeEvmConnectionId;

  // Group EVM connections by lowercased address so one address yields one row,
  // regardless of how many connectors expose it (e.g. Rabby impersonating
  // MetaMask via EIP-6963). Preserve first-seen order.
  const evmGroups = new Map<string, EvmConnectionInput[]>();
  for (const conn of input.evmConnections) {
    const key = walletKey("evm", conn.address);
    const group = evmGroups.get(key);
    if (group) group.push(conn);
    else evmGroups.set(key, [conn]);
  }

  for (const [lowerAddr, conns] of evmGroups) {
    const activeConn = activeConnId
      ? conns.find((c) => c.id === activeConnId)
      : undefined;
    const display =
      activeConn ??
      conns.find((c) => isRealBrandName(c.walletName)) ??
      conns[0];
    const isActive = activeConnId
      ? conns.some((c) => c.id === activeConnId)
      : !!active && lowerAddr === active;

    accounts.push({
      id: (activeConn ?? display).id,
      family: "evm",
      address: display.address,
      label: formatWalletAddress(display.address),
      walletName: display.walletName,
      chainId: display.chainId,
      provider: display.provider,
      walletKind: display.walletKind,
      connectorIds: conns.map((c) => c.id),
      active: isActive,
    });
  }

  const seenSvm = new Set<string>();
  for (const connection of input.svmConnections ?? []) {
    const key = walletKey("svm", connection.publicKey);
    if (seenSvm.has(key)) continue;
    seenSvm.add(key);
    accounts.push({
      id: connection.id ?? connection.walletName ?? connection.publicKey,
      family: "svm",
      address: connection.publicKey,
      label: formatWalletAddress(connection.publicKey),
      walletName: connection.walletName,
      provider: connection.provider,
      walletKind: connection.walletKind,
      active: connection.publicKey === input.activeSvmAddress,
    });
  }

  return accounts;
}

export function buildWalletKitAccounts({
  accounts,
  accountWallets = [],
  transformAccounts,
  canManageAccount,
}: {
  accounts: AomiAccount[];
  accountWallets?: readonly AccountWallet[];
  transformAccounts?: (accounts: AomiAccount[]) => AomiAccount[];
  canManageAccount?: (account: AomiAccount) => boolean;
}): AomiAccount[] {
  const linked = applyStoredWalletLinks(accounts, accountWallets);
  const transformed = transformAccounts ? transformAccounts(linked) : linked;
  if (!canManageAccount) return transformed;
  return transformed.map((account) =>
    canManageAccount(account) ? { ...account, manageable: true } : account,
  );
}

function applyStoredWalletLinks(
  accounts: AomiAccount[],
  wallets: readonly AccountWallet[],
): AomiAccount[] {
  if (wallets.length === 0) return accounts;
  const storedByKey = new Map(
    wallets.map((wallet) => [walletKey(wallet.family, wallet.address), wallet]),
  );
  return accounts.map((account) => {
    const stored = storedByKey.get(walletKey(account.family, account.address));
    if (!stored) return account;
    return {
      ...account,
      linked: true,
      linkedVia: stored.linkedVia,
      capability: stored.capability,
    };
  });
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { Chain } from "viem";
import type { AomiNetworkTarget, SvmNetworkOption } from "./types";
import { resolveSelectedSvmNetwork } from "./catalog/svm-networks";

type WalletNetworkPreferences = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
};

const STORAGE_PREFIX = "aomi.wallet-preferences";

function storageKey(key: string): string {
  return `${STORAGE_PREFIX}.${key}`;
}

function loadWalletNetworkPreferences(key: string): WalletNetworkPreferences {
  try {
    const raw = globalThis.localStorage?.getItem(storageKey(key));
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return {};
    const stored = parsed as WalletNetworkPreferences;
    return {
      selectedEvmChainId:
        typeof stored.selectedEvmChainId === "number"
          ? stored.selectedEvmChainId
          : undefined,
      selectedSolanaNetworkId:
        typeof stored.selectedSolanaNetworkId === "string"
          ? stored.selectedSolanaNetworkId
          : undefined,
    };
  } catch {
    return {};
  }
}

function saveWalletNetworkPreferences(
  key: string,
  prefs: WalletNetworkPreferences,
): void {
  try {
    globalThis.localStorage?.setItem(storageKey(key), JSON.stringify(prefs));
  } catch {
    // localStorage unavailable or over quota — preferences are best-effort.
  }
}

type NetworkPreferencesContextValue = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
  supportedEvmChains: readonly Chain[];
  supportedSolanaNetworks: readonly SvmNetworkOption[];
  selectedSolanaNetwork?: SvmNetworkOption;
  setSelectedEvmChainId: (chainId: number | undefined) => void;
  setSelectedSolanaNetworkId: (networkId: string | undefined) => void;
  selectTarget: (target: AomiNetworkTarget) => void;
};

const NetworkPreferencesContext =
  createContext<NetworkPreferencesContextValue | null>(null);

export function AomiWalletNetworkPreferencesProvider({
  children,
  evmChains,
  solanaNetworks,
  storageKey = "default",
}: {
  children: ReactNode;
  evmChains: readonly Chain[];
  solanaNetworks: readonly SvmNetworkOption[];
  storageKey?: string | null;
}) {
  const [persisted] = useState(() =>
    storageKey ? loadWalletNetworkPreferences(storageKey) : {},
  );

  const [selectedEvmChainId, setSelectedEvmChainId] = useState<
    number | undefined
  >(() =>
    persisted.selectedEvmChainId !== undefined &&
    evmChains.some((chain) => chain.id === persisted.selectedEvmChainId)
      ? persisted.selectedEvmChainId
      : evmChains[0]?.id,
  );
  const [selectedSolanaNetworkId, setSelectedSolanaNetworkId] = useState<
    string | undefined
  >(() =>
    persisted.selectedSolanaNetworkId &&
    solanaNetworks.some((n) => n.id === persisted.selectedSolanaNetworkId)
      ? persisted.selectedSolanaNetworkId
      : resolveSelectedSvmNetwork(solanaNetworks)?.id,
  );

  useEffect(() => {
    if (!evmChains.length) {
      setSelectedEvmChainId(undefined);
      return;
    }
    setSelectedEvmChainId((current) =>
      evmChains.some((chain) => chain.id === current)
        ? current
        : evmChains[0]?.id,
    );
  }, [evmChains]);

  useEffect(() => {
    if (!solanaNetworks.length) {
      setSelectedSolanaNetworkId(undefined);
      return;
    }
    setSelectedSolanaNetworkId((current) =>
      solanaNetworks.some((network) => network.id === current)
        ? current
        : resolveSelectedSvmNetwork(solanaNetworks)?.id,
    );
  }, [evmChains.length, solanaNetworks]);

  useEffect(() => {
    if (!storageKey) return;
    saveWalletNetworkPreferences(storageKey, {
      selectedEvmChainId,
      selectedSolanaNetworkId,
    });
  }, [storageKey, selectedEvmChainId, selectedSolanaNetworkId]);

  const selectedSolanaNetwork = useMemo(
    () =>
      solanaNetworks.length
        ? resolveSelectedSvmNetwork(solanaNetworks, selectedSolanaNetworkId)
        : undefined,
    [selectedSolanaNetworkId, solanaNetworks],
  );

  const value = useMemo<NetworkPreferencesContextValue>(
    () => ({
      selectedEvmChainId,
      selectedSolanaNetworkId,
      supportedEvmChains: evmChains,
      supportedSolanaNetworks: solanaNetworks,
      selectedSolanaNetwork,
      setSelectedEvmChainId,
      setSelectedSolanaNetworkId,
      selectTarget: (target: AomiNetworkTarget) => {
        if (target.family === "evm") {
          setSelectedEvmChainId(target.chainId);
          return;
        }
        setSelectedSolanaNetworkId(target.networkId);
      },
    }),
    [
      evmChains,
      selectedEvmChainId,
      selectedSolanaNetwork,
      selectedSolanaNetworkId,
      solanaNetworks,
    ],
  );

  return (
    <NetworkPreferencesContext.Provider value={value}>
      {children}
    </NetworkPreferencesContext.Provider>
  );
}

export function useAomiWalletNetworkPreferences(): NetworkPreferencesContextValue {
  const context = useContext(NetworkPreferencesContext);
  if (!context) {
    throw new Error(
      "useAomiWalletNetworkPreferences must be used within AomiWalletNetworkPreferencesProvider",
    );
  }
  return context;
}

/**
 * Non-throwing variant for components that may render without a wallet
 * provider in the tree — e.g. a standalone <AomiFrame /> on a docs page or
 * during SSR/prerender, where no wallet kit provider mounts the network
 * preferences context. Returns null when the provider is absent so callers
 * can degrade gracefully instead of crashing the render.
 */
export function useOptionalAomiWalletNetworkPreferences(): NetworkPreferencesContextValue | null {
  return useContext(NetworkPreferencesContext);
}

"use client";

import type {
  SvmCluster,
  SvmNetworkConfigInput,
  SvmNetworkOption,
} from "../types";

export const DEFAULT_SVM_CLUSTER: SvmCluster = "solana:mainnet";

export const DEFAULT_SVM_RPC_HTTP_URLS: Record<SvmCluster, string> = {
  "solana:mainnet": "https://api.mainnet-beta.solana.com",
  "solana:devnet": "https://api.devnet.solana.com",
  "solana:testnet": "https://api.testnet.solana.com",
};

export function getDefaultSvmNetworkLabel(cluster: SvmCluster): string {
  switch (cluster) {
    case "solana:mainnet":
      return "Solana";
    case "solana:testnet":
      return "Solana Testnet";
    case "solana:devnet":
    default:
      return "Solana Devnet";
  }
}

function buildLegacySvmNetwork(
  config?: SvmNetworkConfigInput,
): SvmNetworkOption {
  const cluster = config?.cluster ?? DEFAULT_SVM_CLUSTER;
  return {
    id: cluster,
    label: getDefaultSvmNetworkLabel(cluster),
    cluster,
    rpcHttpUrl: config?.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[cluster],
    rpcWsUrl: config?.rpcWsUrl,
    isDefault: true,
  };
}

export function normalizeSvmNetworkOptions(
  config?: SvmNetworkConfigInput,
): readonly SvmNetworkOption[] {
  const rawNetworks = config?.networks;
  if (!rawNetworks || rawNetworks.length === 0) {
    return [buildLegacySvmNetwork(config)];
  }

  return rawNetworks.map((network, index) => ({
    id: network.id,
    label: network.label || getDefaultSvmNetworkLabel(network.cluster),
    cluster: network.cluster,
    rpcHttpUrl:
      network.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[network.cluster],
    rpcWsUrl: network.rpcWsUrl,
    isDefault:
      network.isDefault ??
      (index === 0 && !rawNetworks.some((item) => item.isDefault)),
  }));
}

export function resolveSelectedSvmNetwork(
  networks: readonly SvmNetworkOption[],
  selectedNetworkId?: string,
): SvmNetworkOption {
  return (
    networks.find((network) => network.id === selectedNetworkId) ??
    networks.find((network) => network.isDefault) ??
    networks[0]
  );
}

export function buildDefaultSvmNetworkOptions(options?: {
  mainnetRpcHttpUrl?: string;
  mainnetRpcWsUrl?: string;
  devnetRpcHttpUrl?: string;
  devnetRpcWsUrl?: string;
  testnetRpcHttpUrl?: string;
  testnetRpcWsUrl?: string;
}): readonly SvmNetworkOption[] {
  return [
    {
      id: "solana-mainnet",
      label: "Solana",
      cluster: "solana:mainnet",
      rpcHttpUrl:
        options?.mainnetRpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS["solana:mainnet"],
      rpcWsUrl: options?.mainnetRpcWsUrl,
      isDefault: true,
    },
    {
      id: "solana-devnet",
      label: "Solana Devnet",
      cluster: "solana:devnet",
      rpcHttpUrl:
        options?.devnetRpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS["solana:devnet"],
      rpcWsUrl: options?.devnetRpcWsUrl,
    },
    {
      id: "solana-testnet",
      label: "Solana Testnet",
      cluster: "solana:testnet",
      rpcHttpUrl:
        options?.testnetRpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS["solana:testnet"],
      rpcWsUrl: options?.testnetRpcWsUrl,
    },
  ];
}

